@r1.t w.request.target request=$r1 family=preference mode=existing determiner=definite fill=description description="the dashed lines rule" thing=$o1
@r1.u1 w.request.unread request=$r1 text="the dashed lines rule" note=pref.revoke.named value="the dashed lines rule"

@r1 w.request.request act=remove mood=do words="Let's clear every preference" predicate=clear
@r1.t w.request.target request=$r1 family=preference mode=existing determiner=quantified fill=all
@r1.u1 w.request.unread request=$r1 text="every preference" note=pref.revoke.all value="every preference"

@prev w.request.previous text="Put new things on the right."
@r1 w.request.request act=remove mood=do words="Roll back the thing I just said" predicate=Roll
@r1.t w.request.target request=$r1 family=preference mode=existing determiner=definite fill=context
@r1.u1 w.request.unread request=$r1 text="the thing I just said" note=pref.revoke.last value="the thing I just said"

@prev w.request.previous text="Always use dashed lines."
@r1 w.request.request act=remove mood=do words="that last one, undo it" predicate=undo
@r1.t w.request.target request=$r1 family=preference mode=existing determiner=definite fill=context
@r1.u1 w.request.unread request=$r1 text="that last one" note=pref.revoke.last value="that last one"

@r1 w.request.request act=ask mood=check question=exists
@r1.t w.request.target request=$r1 family=preference mode=existing determiner=definite fill=description description="a rule about IDs"
@r1.u1 w.request.unread request=$r1 text="a rule about IDs" note=pref.query.exists value="a rule about IDs"

@o1 w.request.context sort=avatar name="My avatar"
@prev w.request.previous text="What is the default?"
@r1 w.request.request act=ask mood=ask words="Tell me the default avatar as well" predicate=Tell question=what
@r1.t w.request.target request=$r1 family=page mode=existing determiner=definite fill=context description="the default avatar" thing=$o1
@r1.u1 w.request.unread request=$r1 text="the default avatar" note=pref.query.default value="the default avatar"
